    ["e568035"] = "DPS de l'arme à distance (ou baguette) :",
    ["270cb3d"] = "Pour ta spécialisation, c'est ce qui compte le plus.",
    ["759646f"] = "DPS de l'arme de mêlée :",
    ["620e128"] = "mais ta spécialisation ne frappe pas avec cette arme et ne l'utilise pas.",
    ["f8fc3c4"] = "ce qui compte pour ta spécialisation.",
    ["4842b23"] = "Les autres différences (armure, dégâts...) ne comptent pas pour ta spécialisation.",
    ["46e81de"] = "Les caractéristiques qui comptent pour toi sont identiques.",
    ["984170a"] = "Pour ta spécialisation, dans cet emplacement ce qui compte surtout : %s.",
    ["8878fa5"] = "La rotation Beast Mastery du guide (montée 1-60) : pas de mêlée ; Hunter's Mark et Serpent Sting en ouverture, faucons (Summon Hawk) à partir du 25, Aimed Shot et Arcane Shot, Multi-Shot et Explosive Trap contre plusieurs monstres. Les capacités à longue recharge (Bestial Wrath, Rapid Fire, raciaux) restent hors de la rotation, à utiliser à la main. Créée par BuildBeast.",
    ["3fcb6ff"] = "Rotation BuildBeast pour monter de 1 à 60, tirée du guide : Hekili ne choisit parmi elles que les capacités que tu as déjà apprises. Créée par BuildBeast.",
    ["f7219d4"] = "pour cette spécialisation BuildBeast n'a pas encore sa propre rotation : Hekili utilise la sienne.",
    ["f23ecca"] = "Hekili n'est pas chargé.",
    ["2ec553f"] = "Je n'ai pas réussi à créer la priorité dans Hekili.",
    ["9e1f59d"] = "Hekili utilise déjà la priorité : %s",
    ["bbf6862"] = "priorité de Hekili définie : %s",
    ["3f1c97f"] = "Hekili n'a pas accepté la priorité.",
    ["511ff29"] = "éclat des touches :",
    ["c172ef4"] = "activé",
    ["72960be"] = "désactivé",
    ["969f47a"] = "Or = à utiliser maintenant, bleu = la suivante.",
    ["2850cfb"] = "ombrage des recharges :",
    ["c4ad91d"] = "visible",
    ["aba8815"] = "masqué",
    ["babe955"] = "chiffres de recharge sur les touches :",
    ["48983fc"] = "activés",
    ["3424735"] = "désactivés",
    ["8b823dc"] = "Zygor n'est pas prêt.",
    ["7496082"] = "marques de talents de Zygor :",
    ["1b9f260"] = "Rouvre la fenêtre des talents.",
    ["7c4161e"] = "Tu changes de cible sans arrêter Auto Shot.",
    ["3ddfa3b"] = "Le familier attaque la cible que tu marques avec Hunter's Mark.",
    ["d00e00c"] = "Une seule touche pour les capacités de mêlée, quand on t'attaque.",
    ["458bcf6"] = "Alterne Mongoose Bite et Counterattack avec une seule touche, après une esquive ou une parade.",
    ["7e3322d"] = "Lance la capacité et démarre l'attaque automatique, même avant d'engager le combat. Tu peux mettre une autre capacité à la place de Heroic Strike. Il faut assez de rage.",
    ["4215a24"] = "Sunder Armor sur l'ennemi sous le curseur, sans le cibler.",
    ["fade647"] = "Blessing of Protection sur l'allié sous le curseur (sinon, sur ta cible).",
    ["0ea3265"] = "Blessing of Freedom sur l'allié sous le curseur.",
    ["474ed6a"] = "Cleanse sur l'allié sous le curseur.",
    ["dd398c9"] = "Invoque l'Advanced Target Dummy au curseur et lui lance Blessing of Protection : appuie deux fois, sans temps de recharge global actif.",
    ["ad171ca"] = "Divine Shield sur toi ; en appuyant de nouveau tu l'enlèves tout de suite. Appuie deux fois, sans temps de recharge global actif.",
    ["8b1f0a2"] = "Démarre l'attaque automatique et lance Holy Strike. Ne la mets pas sur Holy Shield.",
    ["39da0a5"] = "Power Word: Shield sur le curseur, sinon sur toi.",
    ["885b4fd"] = "Greater Heal sur le curseur, sinon sur la cible, sinon sur toi.",
    ["f6044e4"] = "Interrompt l'incantation en cours et relance Greater Heal : pour quand un autre soigneur a déjà soigné cette cible.",
    ["73afb8f"] = "Inner Focus puis tout de suite Prayer of Healing : pour les urgences.",
    ["91996ef"] = "Dispel Magic malin : retire les magies nuisibles aux alliés et bénéfiques aux ennemis.",
    ["b32d1df"] = "Prayer of Mending sur le curseur, sinon sur la cible, sinon sur toi.",
    ["4e5454e"] = "Interrompt l'incantation et utilise Shadow Word: Death sur un monstre presque mort qui s'enfuit ou sur un totem.",
    ["4b2ea52"] = "Applique Deadly Poison sur l'arme de la main droite ; l'icône montre la durée.",
    ["73d1f2d"] = "Applique Instant Poison sur l'arme de la main gauche ; l'icône montre la durée.",
    ["672d6cc"] = "Pick Pocket en ouverture, puis Garrote (tu peux le remplacer par Cheap Shot ou Ambush).",
    ["c2da64b"] = "Envoie familier et personnage à l'attaque avec une seule touche : ainsi tu ne restes pas immobile en montant de niveau.",
    ["8833bc9"] = "Comme BB Attacco, mais lance aussi Stormstrike (à la place de la macro précédente).",
    ["79e760c"] = "Totemic Projection là où se trouve le curseur.",
    ["93ec012"] = "Nature's Swiftness puis tout de suite Healing Wave sur le curseur : soin d'urgence instantané. Retire [@mouseover] si tu ne veux pas le soin au curseur.",
    ["ddfe74e"] = "Polymorph sur la cible focalisée ; s'il n'y en a pas ou si ce n'est pas un ennemi, sur la cible actuelle.",
    ["425c144"] = "Utilise les deux bijoux avec une seule touche (emplacements 13 et 14).",
    ["23fc3c4"] = "Combustion avec les deux bijoux.",
    ["6d5d784"] = "Envoie le familier attaquer puis le met en passif, comme dans le guide.",
    ["3b9d855"] = "Amplify Curse et Bane of Agony ensemble : pour l'ouverture ou quand Amplify Curse est prête.",
    ["67eb4db"] = "Drain Life que tu peux presser plusieurs fois sans l'interrompre.",
    ["c24583f"] = "Corruption sur la cible sous le curseur : pour mettre des DOT sur plusieurs ennemis. Remplace Corruption par un autre DOT.",
    ["de046d0"] = "Fel Domination puis tout de suite Imp : pour rappeler le familier après sa mort, ou pour le build d'exécution.",
    ["0da2d35"] = "Fel Domination puis tout de suite Succubus : pour rappeler le familier après sa mort.",
    ["701f8c9"] = "Bane of Havoc sur la cible sous le curseur.",
    ["6177927"] = "Immolate sur le focus (la cible de Bane of Havoc).",
    ["687eb32"] = "Corruption sur le focus.",
    ["dfc9982"] = "Bane of Doom sur le focus.",
    ["f14c9c9"] = "Bane of Agony sur le focus.",
    ["37f2591"] = "Hurricane qui ne s'interrompt pas tout seul si tu appuies sur la touche pendant l'incantation.",
    ["e041704"] = "Moonfire sur le curseur : pour mettre des DOT sur plusieurs ennemis (passe à Insect Swarm pour l'autre).",
    ["11b387e"] = "Feral Charge (chat) puis Prowl, si tu n'es pas déjà furtif.",
    ["9bca5ec"] = "Change de forme pour te libérer des racines et des ralentissements : d'ours en chat, de chat en chat.",
    ["38e0846"] = "Une seule touche : Aquatic Form dans l'eau, Travel Form en extérieur, sinon Cat Form.",
    ["53406a7"] = "Entre en Dire Bear Form une seule fois, sans en sortir si tu appuies de nouveau.",
    ["b18da61"] = "Growl sur le focus, puis sur le curseur, puis sur la cible.",
    ["beb6029"] = "Nature's Swiftness puis tout de suite Healing Touch : soin d'urgence instantané (sort de la forme et interrompt l'incantation).",
    ["8c5c182"] = "Impossible de créer des macros en combat : réessaie plus tard.",
    ["e3c93a8"] = "Macros : %d créées, %d mises à jour%s. Ouvre-les avec /macro et glisse-les sur tes barres.",
    ["99effc3"] = "%d non créées (tu as déjà 18 macros de personnage)",
    ["530c645"] = "Il n'y a pas de macros pour cette spécialisation.",
    ["1e74c8f"] = "BuildBeast va créer %s macros pour ton personnage :\n%s\n\nSi elles existent déjà, il les met à jour. Ensuite tu les glisses sur tes barres.",
    ["d8354a3"] = "Créer",
    ["160009a"] = "Annuler",
    ["054716f"] = "Guerrier",
    ["3e76e85"] = "Paladin",
    ["69c8129"] = "Chasseur",
    ["dd6c053"] = "Voleur",
    ["3a3f441"] = "Prêtre",
    ["fabeb14"] = "Chaman",
    ["a5a0a92"] = "Mage",
    ["8b0635d"] = "Démoniste",
    ["3d8e8ed"] = "Druide",
    ["ce774d9"] = "OUI",
    ["c2f3f48"] = "NON",
    ["672c529"] = "SIMILAIRE",
    ["656ff24"] = "Bear Form, Growl, Maul (quête de classe), Nature's Grasp, Demoralizing Roar",
    ["50d1ea3"] = "Bash ; quête pour Cure Poison",
    ["2290f2a"] = "Swipe ; quête pour Aquatic Form",
    ["227f378"] = "Faerie Fire (maintenant aussi dans les formes), Hibernate",
    ["469f184"] = "Cat Form (quête), Prowl, Claw, Rip, Shred, Starfire, Rebirth, Omen of Clarity",
    ["eda7053"] = "Mark of the Wild sur toi. Ouvre avec Wrath et continue à le lancer. Quand le mana est bas, finis le monstre avec l'arme, ainsi le mana revient. Soigne-toi avec Healing Touch entre les combats.",
    ["3d495a9"] = "Garde Mark of the Wild et Thorns sur toi et lance Rejuvenation avant d'engager. Ouvre avec Wrath, ajoute Moonfire et continue avec Wrath. Dans une zone bondée, ouvre avec Moonfire, qui est instantané.",
    ["bb21cc8"] = "La quête de classe te donne Bear Form, Growl et Maul. Nature's Grasp enracine le prochain monstre qui te frappe ; Demoralizing Roar est pour la forme d'ours.",
    ["a9ba21f"] = "Enrage te donne de la rage tout de suite et davantage en 10 secondes, mais baisse ton armure.",
    ["9c7f3ca"] = "Feral est la spécialisation chat et ours, et celle qui monte le plus en douceur : Prowl et Dash te mènent d'un objectif à l'autre et tu ne t'arrêtes presque jamais pour le mana. En Bear Form : Mark of the Wild et Thorns sur toi, et laisse la rage de tes coups payer Maul, qui ajoute des dégâts au coup suivant. Contre plusieurs monstres, Demoralizing Roar pour les affaiblir.",
    ["ce230c2"] = "En Bear Form : Enrage avant le pull (la perte d'armure pèse moins), Faerie Fire baisse l'armure du monstre, Swipe est le remplissage et Maul dépense la rage qui reste. Avec plusieurs monstres, Demoralizing Roar d'abord, puis Swipe.",
    ["78a0920"] = "Cat Form : d'abord Mark of the Wild et Thorns. Ouvre depuis Prowl avec Shred (Prowl te place derrière le monstre), puis Faerie Fire, puis Claw pour accumuler des points de combo ou Shred quand tu es derrière. Avec quatre points de combo ou plus, Rip si le monstre vit assez longtemps. Bear Form reste meilleure contre plusieurs monstres : la forme de chat n'a rien qui frappe plus d'un monstre.",
    ["540175c"] = "Rake : ouvre depuis Prowl avec Shred, Faerie Fire, puis Rake et garde son saignement toujours actif sur un monstre qui vit assez longtemps ; puis Claw ou Shred par derrière. Avec 4 points ou plus : Rip si le monstre vit, Ferocious Bite pour finir.",
    ["87e3251"] = "Lacerate (ours) : un saignement qui s'accumule jusqu'à 5 fois ; contre un seul monstre c'est ton remplissage, et Maul dépense la rage qui reste. Avec plusieurs monstres Demoralizing Roar puis Swipe. Blood Frenzy : en ours chaque critique donne 5 de rage, en chat un critique avec une capacité à points de combo en donne un de plus.",
    ["25dc320"] = "Predatory Discipline : Ferocious Bite gagne encore des dégâts grâce à l'énergie en plus, mais ne la dépense pas.",
    ["042c952"] = "Ravage : ouvre depuis Prowl avec Ravage (tu dois être derrière le monstre), puis Faerie Fire, Rake avec le saignement toujours actif, puis Claw ou Shred par derrière ; avec 4 points ou plus Rip ou Ferocious Bite pour finir. Poised retire 10 d'énergie à ton premier coup si tu commences à pleine énergie.",
    ["4560b4d"] = "Dire Bear Form : Enrage avant le pull, Faerie Fire, Primal Bite à chaque recharge (une morsure puissante avec 6 secondes de recharge et beaucoup de menace), Lacerate entre les deux contre un seul monstre et Maul pour dépenser le reste ; avec plusieurs monstres Demoralizing Roar et Swipe à la place de Lacerate.",
    ["ff10d54"] = "Chat : Shifting Power quand tu as moins de 50 d'énergie (transforme le mana en 40 d'énergie, 8 secondes de recharge).",
    ["0d8ecd7"] = "Feral veut avant tout les dégâts par seconde de l'arme, parce que ta forme s'appuie dessus, et la vitesse de l'arme ne compte pas. Ensuite Toucher (Hit), critique, Agilité et Force.",
    ["4a841e3"] = "Guardian est l'ours : il utilise le même plan de talents que Feral. Bear Form avec Mark of the Wild et Thorns sur toi ; la rage de tes coups paie Maul. Contre plusieurs monstres Demoralizing Roar.",
    ["7b551a8"] = "Enrage avant le pull, Faerie Fire sur le monstre, Swipe comme remplissage et Maul avec la rage qui reste. Avec plusieurs monstres Demoralizing Roar puis Swipe.",
    ["af4c8fb"] = "Lacerate est ton remplissage contre un seul monstre (il s'accumule jusqu'à 5 fois) ; Maul dépense la rage qui reste. Avec plusieurs monstres Demoralizing Roar et Swipe.",
    ["5213241"] = "Dire Bear Form : Enrage avant le pull, Faerie Fire, Primal Bite à chaque recharge (6 secondes, beaucoup de menace), Lacerate entre les deux contre un seul monstre et Maul pour le reste ; avec plusieurs monstres Demoralizing Roar et Swipe à la place de Lacerate.",
    ["fc61247"] = "L'ours veut les dégâts par seconde de l'arme (la vitesse ne compte pas), puis Toucher (Hit), critique, Agilité et Force. Pour la forme d'ours, Force et puissance des sorts conviennent aussi, et l'Endurance compte davantage si tu tankes.",
    ["25acd2a"] = "Balance et Restoration commencent pareil : Improved Wrath (une demi-seconde d'incantation en moins et moitié de mana) et Nature's Focus. Balance démarre lentement, mais accélère quand Insect Swarm s'ajoute à Moonfire sur chaque monstre.",
    ["9c1fb9f"] = "Mark of the Wild et Thorns sur toi, Rejuvenation avant d'engager. Ouvre avec Wrath, ou avec Moonfire si la zone est bondée. Moonfire et Insect Swarm sur le monstre (un DOT qui réduit aussi sa chance de toucher), puis Wrath. Regrowth si tu as besoin de soins, Nature's Grasp avant qu'un deuxième monstre n'arrive.",
    ["7f51b3b"] = "Moonfire et Insect Swarm sur chaque monstre que tu combats, puis Wrath. Avec trois monstres ou plus, Hurricane.",
    ["c845919"] = "Avec trois monstres ou plus, Barkskin puis Hurricane.",
    ["d66aa4c"] = "Eclipse : chaque Wrath retire une demi-seconde à tes deux Starfire suivants, si bien que Starfire entre enfin dans la rotation : un Wrath suivi de deux Starfire.",
    ["7e94c11"] = "Moonkin Form : beaucoup d'armure, 3 % de critique pour le groupe et Omen of Clarity se déclenche deux fois plus souvent ; tu ne peux pas lancer de soins sous cette forme, donc sors pour Regrowth et rentre à nouveau. Rotation : Moonfire et Insect Swarm, puis un Wrath et deux Starfire.",
    ["ef6797a"] = "Pour Balance et Restoration la puissance des sorts passe en premier, puis Intelligence, critique et Esprit ; Restoration ajoute la puissance de soins au 60. Un bâton de lanceur peut venir d'une quête de faction.",
    ["a91a8ac"] = "Restoration est la plus lente à monter, parce que soigner ne tue pas les monstres : tu peux monter en Balance ou en Feral et soigner quand même les donjons.",
    ["7a2110b"] = "Mark of the Wild et Thorns sur toi, Rejuvenation avant d'engager. Ouvre avec Wrath ou Moonfire dans une zone bondée, puis Moonfire et Insect Swarm sur le monstre et Wrath. Regrowth si tu as besoin de soins, Nature's Grasp avant qu'un deuxième monstre n'arrive.",
    ["937f66e"] = "Swiftmend : soin instantané sur celui qui a ton Rejuvenation ou Regrowth. Quand tu subis des dégâts, Swiftmend sur ton Rejuvenation puis Regrowth si besoin de plus. Avec trois monstres ou plus, Hurricane.",
    ["2061d06"] = "Nature's Swiftness : ton prochain sort de nature est instantané. Laisse-le hors de la rotation, pour le moment où il te faut un gros soin tout de suite.",
    ["1164b95"] = "Wild Growth : soigne la cible et son groupe sur 7 secondes, plus fort au début : en groupe quand plusieurs personnes sont blessées.",
    ["8f8a34a"] = "Aspect of the Hawk, apprivoiser le familier (quête de classe : Tame Beast, Call Pet, Feed Pet, Revive Pet)",
    ["2b3db50"] = "Auto Shot démarre tout seul : reste immobile une demi-seconde avant chaque tir et laisse venir le monstre. Raptor Strike s'il t'atteint. À moins de 8 mètres les tirs à distance ne marchent pas.",
    ["9329f10"] = "Ajoute Serpent Sting en ouverture, seulement sur des monstres qui durent : s'il meurt en quelques secondes les dégâts sont perdus.",
    ["d2b7bf1"] = "Hunter's Mark avant le pull, puis Serpent Sting. Arcane Shot quand tu as du mana.",
    ["85f72cd"] = "Le cœur est Auto Shot, avec Arcane Shot quand tu as du mana. Avant le pull Hunter's Mark, puis Serpent Sting en ouverture. Pendant que le monstre court vers toi, Concussive Shot le ralentit ; Raptor Strike s'il t'atteint.",
    ["71067ff"] = "Tu as le familier : envoie-le devant quelques secondes, puis Serpent Sting. Garde toujours Aspect of the Hawk et nourris le familier. Concussive Shot si le monstre se retourne contre toi, Raptor Strike en dernier recours.",
    ["bb6f64b"] = "Rapid Fire (+40 % de vitesse d'attaque pendant 15 secondes) reste hors de la rotation : garde-le pour le pull qui en a besoin.",
    ["ebe54cf"] = "Le cœur est Aimed Shot à chaque fois qu'il est prêt (2 secondes d'incantation, 6 secondes de recharge partagées avec Multi-Shot), avec Auto Shot dans les trous. Avant le pull Hunter's Mark, familier devant, puis Serpent Sting. Arcane Shot quand tu as du mana. Si le monstre t'atteint : Disengage. Avec plusieurs monstres : Multi-Shot à la place d'Aimed Shot.",
    ["c943332"] = "Le cœur ce sont les faucons (Summon Hawk) : chaque faucon dure 18 secondes, deux peuvent être dehors ; invoque un nouveau faucon quand l'un des deux expire. Puis Aimed Shot quand il est prêt et Auto Shot dans les trous. Arcane Shot utilise la même recharge que les faucons, donc attends après eux. Le reste comme avant.",
    ["ab9f050"] = "Ajoute Intimidation : si le monstre se retourne contre toi, il l'étourdit et donne de la menace au familier ; Disengage quand elle n'est pas prête. Avec plusieurs monstres : Explosive Trap d'abord, puis Multi-Shot sur la recharge d'Aimed Shot.",
    ["bf06335"] = "Bestial Wrath (2 minutes) et Volley restent hors de la rotation : utilise-les à la main sur les pulls dangereux ou avec de grands groupes. À partir du 42 presque tous les points vont dans Marksmanship : la rotation ne change pas.",
    ["e096af7"] = "Beast Mastery tire de loin : comptent le DPS de l'arme à distance puis l'Agilité. L'arme de mêlée ne sert que pour ses caractéristiques.",
    ["b35c3c9"] = "Le cœur est Aimed Shot à chaque fois qu'il est prêt, avec Auto Shot dans les trous. Après l'avance du familier, le premier tir doit être le plus fort : avec Rapid Killing en attente, c'est Aimed Shot. Avant le pull Hunter's Mark et familier devant ; Serpent Sting sur chaque monstre, car s'il meurt avec Serpent Sting dessus, ton prochain tir dans les 20 secondes fait jusqu'à 20 % de plus. Arcane Shot quand tu as du mana. Si le monstre t'atteint : Disengage. Avec plusieurs monstres : Multi-Shot à la place d'Aimed Shot.",
    ["cf4e14e"] = "Avant le pull aussi Trueshot Aura, en plus de Hunter's Mark.",
    ["51e16cf"] = "Sniper Shot est ton tir le plus fort : 4 secondes d'incantation, 15 secondes de recharge, jusqu'à 45 mètres, et pendant 10 secondes tes trois tirs suivants portent 10 mètres plus loin. Utilise-le comme premier tir après l'avance du familier quand tu as le temps pour l'incantation, mieux avec Rapid Killing en attente ; sinon Aimed Shot. Avec plusieurs monstres : Explosive Trap d'abord, puis Multi-Shot sur la recharge d'Aimed Shot.",
    ["c8aaa16"] = "Le cœur ce sont les faucons (Summon Hawk) : un nouveau chaque fois que l'un des deux expire. Puis Aimed Shot quand il est prêt et Auto Shot dans les trous ; Sniper Shot comme premier tir si tu as le temps. Arcane Shot attend après les faucons.",
    ["1fe9ee6"] = "Marksmanship tire de loin : comptent le DPS de l'arme à distance (à égalité, mieux vaut une plus lente avec de gros coups, car Aimed Shot repose sur un coup d'arme) et l'Agilité. Avec Careful Aim l'Intelligence compte aussi comme puissance d'attaque, en plus du mana. L'arme de mêlée ne sert que pour ses caractéristiques.",
    ["184fc61"] = "Survival combat à deux endroits. À distance : Multi-Shot à chaque fois qu'il est prêt (il est instantané et partage sa recharge avec Aimed Shot, donc tu n'utilises presque pas Aimed Shot), plus Serpent Sting, Arcane Shot et Auto Shot. En mêlée : Immolation Trap, puis Raptor Strike (instantané, 6 secondes de recharge) et Mongoose Bite après une esquive. Hunter's Mark avant le pull et le familier entre en premier.",
    ["d85837a"] = "Strider Kick : un coup de pied avec tous les dégâts de l'arme qui te rend 30 % plus rapide pendant 3 secondes : c'est la touche qui termine la mêlée et te ramène à distance. En mêlée d'abord Immolation Trap, Mongoose Bite quand il est utilisable, Raptor Strike. À distance Multi-Shot quand il est prêt, Serpent Sting, Arcane Shot, Auto Shot. Avec plusieurs monstres Explosive Trap prend la place d'Immolation Trap, car une seule recharge vaut pour tous les pièges.",
    ["e7233e1"] = "Avec Lacerating Strikes chaque Mongoose Bite laisse un saignement égal à 40 % des dégâts du coup, sur 21 secondes.",
    ["10bfe36"] = "Survival tire mais frappe aussi avec l'arme de mêlée (Raptor Strike et Strider Kick reposent sur ses dégâts) : une deux mains lente aide. Ensuite compte l'Agilité. À partir du 49 Careful Aim rend l'Intelligence utile aussi comme puissance d'attaque.",
    ["0718298"] = "Blink, Evocation, Mana Shield, Blizzard, Fire Ward, téléportation vers deux capitales (et Arcane Blast pour Arcane et Fire)",
    ["ad986c1"] = "Conjure Mana Agate (la première gemme de mana)",
    ["3e67dd9"] = "Ice Armor ; quête de classe (la baguette Ice Fury)",
    ["3ddbf7c"] = "Frostfire Bolt, premiers portails",
    ["3d9e7fb"] = "Garde toujours Arcane Intellect et un sort d'armure (pour l'instant Frost Armor). La régénération de mana s'arrête 5 secondes après chaque sort qui coûte du mana : un monstre presque mort ne vaut pas une incantation complète. Vers le niveau 5 prends une baguette (un Enchanteur te fabrique la Lesser Magic Wand, la Greater Magic Wand à partir du 13) : jusqu'aux talents elle peut faire autant de dégâts que tes sorts ou plus et ne dépense pas de mana.",
    ["2991425"] = "Ouvre avec Frostbolt à portée maximale, ainsi le monstre arrive ralenti. Continue à lancer pendant qu'il approche, puis Fire Blast pour finir et la baguette pour ce qui reste.",
    ["5d6b9a7"] = "Frost Nova gèle tout autour de toi : les dégâts la brisent, donc tu peux reculer et continuer à lancer. Si le monstre arrive en mêlée : Frost Nova et recule.",
    ["11f2d67"] = "Avec Missile Barrage : ouvre de loin avec Frostbolt (Arcane et Frost) ou Fireball (Fire), continue à lancer et quand le proc se déclenche lance Arcane Missiles : ils deviennent une volée gratuite. Missile Barrage est le talent qui te fait économiser le plus de mana pendant la montée.",
    ["b985201"] = "Evocation est une canalisation de 8 secondes qui te rend une grande partie du mana. Blink à chaque recharge en courant te fait arriver environ un cinquième plus vite. La pierre de foyer vaut mieux pour la zone de quêtes, car la téléportation t'amène déjà dans une capitale.",
    ["a601e53"] = "Arcane Blast : chaque incantation te donne des dégâts de sorts égaux à 12 % de ton Intelligence, jusqu'à 4 charges qui durent 18 secondes ; chaque charge fait coûter 100 % de plus la prochaine incantation. Frostbolt de loin, puis Arcane Blast une à trois fois jusqu'à ce que Missile Barrage se déclenche, puis Arcane Missiles. Laisse les charges expirer plutôt que d'arriver à quatre. Dépense Clear Casting sur un Arcane Blast chargé. En mêlée : Frost Nova et recule. Fire Blast pour finir et la baguette.",
    ["e55eb73"] = "Arcane Wrath : un coup lourd avec 6 secondes de recharge (les dégâts en plus valent 5 % de ton mana maximum). Frostbolt de loin, puis Arcane Wrath, Arcane Blast une à trois fois jusqu'à Missile Barrage et Arcane Missiles ; Frost Nova quand il approche, à nouveau Arcane Wrath, puis Fire Blast et la baguette pour tuer. Laisse les charges expirer sinon le coût croissant te vide ; Clear Casting seulement sur un Arcane Blast chargé ou un Arcane Wrath, jamais sur un sort bon marché.",
    ["65a5bf0"] = "Presence of Mind : ton prochain sort avec une incantation de moins de 10 secondes est instantané.",
    ["c51b464"] = "Arcane Power : +30 % de dégâts pendant 15 secondes, au prix de +30 % de mana.",
    ["dfc4101"] = "Ouvre avec Pyroblast ou Frostbolt de loin, puis Arcane Wrath. Arcane Blast une à trois fois jusqu'à Missile Barrage, puis les missiles. À partir du 58 Fire Blast à chaque recharge et Pyroblast quand Heating Up atteint 3 charges.",
    ["9226a40"] = "Pour chaque spécialisation la puissance des sorts passe en premier, parce que tes sorts progressent beaucoup avec elle. L'Intelligence augmente le mana et un peu le critique ; l'Esprit réduit les pauses pour boire, et pour Arcane il compte beaucoup car elle consomme vite son mana.",
    ["ebbbb02"] = "Fireball de loin. Un ou deux Arcane Blast jusqu'à ce que Missile Barrage se déclenche, puis les missiles. Fire Blast à chaque recharge. Un monstre avec peu de vie n'a pas besoin d'être gardé à distance : laisse-le te frapper quelques fois, sous 15 % la baguette le finit.",
    ["9e5f918"] = "Scorch remplit les trous même avec le monstre sur toi.",
    ["ab79a6b"] = "Ouvre avec Frostfire Bolt de loin, puis un ou deux Arcane Blast jusqu'à ce que Missile Barrage se déclenche et les missiles. Fire Blast à chaque recharge, Scorch pour remplir les trous, la baguette pour les derniers 15 %.",
    ["bece8ec"] = "Pyroblast et Heating Up : chaque critique non périodique de Fireball, Frostfire Bolt, Fire Blast ou Scorch rend ton prochain Pyroblast un quart plus rapide, jusqu'à 3 charges, et Fire Blast ajoute une charge à chaque dégât. Lance Pyroblast quand Heating Up atteint 3 charges.",
    ["196edb9"] = "Pour chaque spécialisation la puissance des sorts passe en premier. L'Intelligence augmente le mana et un peu le critique ; l'Esprit réduit les pauses pour boire.",
    ["38bc29a"] = "Frost commence par Precision : deux points portent la chance de toucher les monstres de ton niveau à 100 %.",
    ["c690916"] = "Frostbite : tes effets de givre ont 15 % de chances de geler la cible pendant 5 secondes. Ice Lance (à partir du 27) : contre une cible gelée elle fait 300 % de plus, avec 8 secondes de recharge partagées avec Fire Blast.",
    ["1f1ed9a"] = "Frostbolt de loin, et continue à lancer pendant que le monstre arrive. Quand Frostbite gèle la cible : un Frostbolt avec Ice Lance juste derrière ; si Ice Lance n'est pas prête, Cone of Cold. En mêlée : Frost Nova et recule, puis Frostbolt et Ice Lance sur le monstre gelé. Missile Barrage : lance les missiles, ou garde-le pour le prochain monstre si celui-ci est presque mort. Fire Blast ou la baguette pour un monstre bas non gelé.",
    ["2e43c7c"] = "Avec Fingers of Frost tes deux prochains sorts traitent la cible comme gelée : le premier sur un Frostbolt, le second sur un Frostbolt avec Ice Lance (ou avec Cone of Cold si Ice Lance n'est pas encore prête). Sa force est dans les 30 : après Shatter une cible gelée subit tes coups les plus durs.",
    ["cecd125"] = "Ice Barrier d'abord, et relance-le quand la minute se termine : en plus du bouclier il donne 15 % de dégâts de givre en plus pendant une minute.",
    ["959453a"] = "Winter's Chill : Frostbolt et Ice Lance l'accumulent sur la cible jusqu'à 5 fois, et le prochain Cone of Cold fait 20 % de plus par charge.",
    ["5a9d3eb"] = "Redemption (quête de classe)",
    ["3d343ad"] = "Seal of Command (talent Retribution), Seal of Justice",
    ["32b558d"] = "Double spécialisation et monture",
    ["38d0905"] = "Avant le pull Blessing of Might et Devotion Aura. Puis trois étapes : Seal of Righteousness, Judgment en courant vers le monstre, Holy Strike. Ensuite, Judgment et Holy Strike à chaque fois qu'ils sont prêts, et rafraîchis le sceau seulement quand il va se terminer (Judgment ne le consomme plus et est hors du temps de recharge global). Le mana est aussi ton soin : si le prochain coup tue le monstre, saute la touche. Si tu termines un combat avec du mana en trop, transforme-le en vie avec Holy Light. En danger : d'abord Divine Protection sur toi, puis soigne-toi.",
    ["f580de7"] = "Consecration quand tu combats plusieurs ennemis ou as du mana en plus : il coûte plus que Judgment et Holy Strike ensemble et a besoin de 8 secondes pour faire tous ses dégâts. Exorcism sur chaque mort-vivant ou démon, même à 30 mètres.",
    ["2ea2c89"] = "Ajoute Hammer of Wrath : il achève les ennemis sous 20 % de vie.",
    ["c8d4778"] = "Retribution et Protection commencent dans le même arbre avec presque les mêmes talents. À la place de Deflection (5 % de parade) tu peux choisir Benediction : toutes les capacités instantanées coûtent 10 % de mana en moins, et Consecration devient plus facile à payer.",
    ["a81d5b1"] = "Avec Seal of Command : Blessing of Kings ou Might et Retribution Aura. Sur un monstre qui dure : d'abord le Judgment de Seal of the Crusader (le monstre subit plus de dégâts sacrés), puis passe à Seal of Command si tu as une arme lente ; avec une arme rapide ou beaucoup de dégâts de sorts, Seal of Righteousness est meilleur. Ensuite Judgment et Holy Strike à chaque recharge. Astuce : le Judgment de Seal of Command fait presque le double contre une cible étourdie, donc ouvre avec Hammer of Justice puis Judgment.",
    ["733e5e6"] = "Sacred Arbiter : Holy Strike frappe 20 % plus fort et rafraîchit chaque Judgment sur la cible, même ceux d'autres paladins.",
    ["a01f90a"] = "Champion of the Light transforme jusqu'à 60 % de ton Intelligence en dégâts de sorts : l'équipement avec puissance des sorts devient encore meilleur. Au 40 Unsealed Wrath : les coups conservent une copie du sceau actif (jusqu'à 3), et changer de sceau redevient intéressant.",
    ["5f3698b"] = "L'arme est la chose la plus importante : idéalement avec puissance des sorts et beaucoup de dégâts. Avec Seal of Command les armes lentes et lourdes sont les meilleures (Holy Strike et le sceau font plus de dégâts). Pour le reste d'abord Force ou puissance d'attaque, puis Endurance, puis puissance des sorts.",
    ["4c063de"] = "Holy commence comme Retribution : les 12 premiers points (jusqu'au niveau 21) vont dans Retribution, pour plus d'efficacité en mana et Pursuit of Justice. Jusqu'au 20 tes soins sont Holy Light, Lay on Hands et Blessing of Protection : en quête en solo utilise Seal of Righteousness, Judgment et Holy Strike comme un paladin de dégâts, sans gaspiller de mana.",
    ["e1a4083"] = "Avec Flash of Light tu as deux soins : Holy Light est lent et puissant, pour quand il faut beaucoup de vie et qu'il y a le temps ; Flash of Light est rapide et coûte moins, pour des dégâts faibles et constants. Choisir le bon soin, c'est tout le travail : le mauvais brûle du mana. Dès le 20 aussi Consecration, Exorcism et Blessing of Kings.",
    ["42143bb"] = "À partir du 22 les points vont dans Holy : Spiritual Focus (les coups que tu subis retardent moins tes sorts), puis Reverence (une partie de la régénération de mana continue pendant que tu lances) et Healing Light (plus de soins pour Holy Light, Flash of Light et Holy Shock).",
    ["a1c4391"] = "Comment soigner : si le tank subit des dégâts constants utilise Flash of Light ou Holy Light ; pour des dégâts soudains Holy Shock ; en urgence Lay on Hands (dépense tout ton mana). Blessing of Protection sur un allié qui subit des dégâts physiques, jamais sur le tank : s'il devient immunisé les ennemis se tournent vers les autres.",
    ["e98c82f"] = "Illumination : un soin critique de Flash of Light, Holy Light ou Holy Shock peut te rendre du mana (la moitié du coût de base), donc l'Intelligence et le critique comptent. Dès le 37 Oath of Light sur la cible principale ; dès le 38 Infusion of Light : un soin critique de Holy Shock ou Flash of Light rend ton prochain Holy Light plus rapide.",
    ["3bb92dd"] = "Au 40 tu as la double spécialisation (garde Retribution comme deuxième spé pour les quêtes en solo) et les armures de plaques. Dès le 42 Holy Shock : un soin instantané avec 10 secondes de récupération, ou des dégâts sacrés sur un ennemi. Dès le 45 Divine Favor : ton prochain soin est toujours critique (2 minutes de récupération), pour quand le tank est en danger. Dès le 47 Holy Power rend plus probables les critiques de Holy Shock et Holy Strike.",
    ["31364c3"] = "Light's Vigil : un effet de 30 secondes sur un allié ; un Holy Shock sur la même cible le déclenche, soigne aussi le groupe et ne lance pas la récupération de Holy Shock. Il coûte cher et il ne peut y en avoir qu'un par groupe : garde-le pour les dégâts sur plusieurs joueurs. Sur un ennemi il rend 75% du mana. Les derniers points (dès le 56) vont dans Divine Intellect.",
    ["7fda0df"] = "Pour Holy, la puissance de soins vient en premier, puis l'Intelligence (plus de mana et plus de critiques, qui rendent du mana via Illumination), puis le mana par 5 secondes et l'Esprit (avec Reverence une partie de la régénération continue pendant que tu lances). L'arme compte pour ses statistiques, pas pour ses dégâts : une masse avec soins et Esprit vaut mieux qu'une arme avec plus de DPS. Mailles jusqu'au 40, puis plaques, mais une pièce de tissu avec les bonnes statistiques vaut plus qu'une de mailles sans.",
    ["a531e3f"] = "Seal of Fury est le sceau du tank : chaque coup fait des dégâts sacrés en plus et avec le bouclier tu obtiens une absorption égale à la moitié de ces dégâts. Son Judgment te fait provoquer pendant 3 secondes à 10 mètres. Righteous Fury augmente toute ta menace de 33 %. À partir du 22 tu passes dans l'arbre Protection, après Pursuit of Justice.",
    ["8279baa"] = "Blessing of Kings, Retribution Aura et Righteous Fury actif. Garde toujours Seal of Fury. Juge en courant vers le monstre pour provoquer. Pose Consecration dès que tu es en mêlée, si le mana le permet. Puis Holy Strike à chaque recharge et Exorcism sur morts-vivants et démons. Rassemble jusqu'à quatre ennemis et brûle tout avec Consecration.",
    ["34e2900"] = "Shield Specialization : un blocage te rend 4 % du mana maximum, au plus toutes les 3 secondes : c'est une grande partie de ton mana.",
    ["cc3ac76"] = "Templar's Bulwark : un bouclier qui absorbe des dégâts égaux à toute ta vie pendant 8 secondes, mais te donne Forbearance pendant une minute. À partir du 37 Swift Judgement : le Judgment du sceau part tout seul avec 1 minute de recharge, donc tu as une deuxième provocation.",
    ["be55413"] = "Holy Shield : pendant 10 secondes tu bloques plus souvent et jusqu'à 4 blocages font des dégâts sacrés. Reckoning (à partir du 43) peut donner une attaque en plus après un blocage ou un coup critique subi.",
    ["e76d8e9"] = "Pour Protection la puissance des sorts passe en premier (Seal of Fury, Holy Shield et Consecration font des dégâts sacrés), puis Force et Endurance. Pour l'arme mieux vaut une plus rapide : Seal of Fury frappe à chaque coup. Une arme avec puissance des sorts peut valoir un peu moins de dégâts.",
    ["05e5db7"] = "Shadow Word: Pain ; courte quête de classe (une robe)",
    ["c95888a"] = "Mind Blast, Resurrection ; la quête de race enseigne la première capacité seulement de ta race",
    ["091c0cd"] = "Holy Fire, Flash Heal, Devouring Plague, Fear Ward, Mind Soothe, Shackle Undead ; la deuxième capacité raciale",
    ["71b2a72"] = "Fortitude sur toi avant le pull. Ouvre avec Smite, mets Shadow Word: Pain sur la cible et finis-la à la baguette, qui ne coûte pas de mana et au début fait une grande partie de tes dégâts (reste immobile une demi-seconde avant de l'utiliser). Si le monstre t'atteint, Power Word: Shield d'abord. Le plus important est d'avoir une bonne baguette : remplace-la chaque fois que tu en trouves une meilleure.",
    ["e023128"] = "Mind Blast est le coup fort à recharge courte. Les sept premiers points de talent sont les mêmes pour toutes les spécialisations : Wand Specialization (10-11) et Spirit Tap (12-16). Avec Spirit Tap, chaque mort d'un monstre qui donne de l'expérience double ton Esprit pendant 15 secondes et pendant ce temps la moitié de la régénération de mana continue pendant que tu lances : moins de pauses pour boire.",
    ["8df287d"] = "Inner Fire : armure en plus, chaque coup reçu utilise une charge. Garde-le, avec Fortitude, toujours sur toi et relance-le quand il se termine.",
    ["bebe913"] = "Psychic Scream fait fuir les ennemis proches, mais attention : ils peuvent ramener d'autres monstres.",
    ["ffa87bf"] = "Le maître t'enseigne aujourd'hui plus qu'à tout autre niveau : Holy Fire (ouverture lente mais forte, brûle aussi dans le temps), Flash Heal (rapide mais coûteux), Devouring Plague (dégâts dans le temps qui te soignent) et d'autres.",
    ["084f80e"] = "Shadow est la spécialisation recommandée pour monter seul : les points vont dans Shadow Word: Pain, Mind Blast et Mind Flay, ainsi les monstres meurent plus vite.",
    ["f33a503"] = "Mets Shield sur toi si le monstre t'atteint. Ouvre avec Mind Blast, puis Shadow Word: Pain. À partir du 27 aussi Devouring Plague et Mind Flay, et après Shadow Word: Pain ajoute Vampiric Embrace pour que tes dégâts d'ombre te soignent. Puis finis à la baguette. Si le mana est bas, saute Devouring Plague et Mind Flay.",
    ["496ef3d"] = "Shadow Word: Death est un dégât soudain, mais si la cible survit tu subis 30 % de ta vie maximale : garde-le pour le coup final.",
    ["edd0d02"] = "Shadowform : reste en Shadowform pendant que tu combats (+10 % de dégâts d'ombre, les sorts d'ombre coûtent moitié de mana, -15 % de dégâts physiques, mais tu ne peux pas lancer de soins : sors avant de te soigner). Ouvre avec Mind Blast, puis Shadow Word: Pain, Vampiric Embrace, Devouring Plague et Mind Flay. Quand un coup de plus tue le monstre : Shadow Word: Death, ou laisse le dernier morceau à la baguette. Shield sur toi si le monstre t'atteint.",
    ["b912dce"] = "Pour Shadow la puissance des sorts passe en premier (celle d'ombre convient aussi : presque tous tes dégâts sont d'ombre), puis critique et Toucher (Hit). La baguette est très importante : au début elle fait une grande partie des dégâts.",
    ["8e3f775"] = "Discipline est la spécialisation de soins que nous recommandons pour jouer seul : à partir du 20 Power in Light ajoute des dégâts à Smite.",
    ["916c9c2"] = "Ouvre avec Holy Fire de loin, Smite pendant que le monstre arrive, puis Mind Blast, Shadow Word: Pain et la baguette. Si le combat tourne mal : Shield sur toi, puis soigne-toi : Flash Heal si tu en as besoin vite, Heal si tu as le temps.",
    ["a80f7e5"] = "Penance : une rafale de coups sacrés qui blesse un ennemi ou soigne un allié, 12 secondes de recharge, le premier coup part tout de suite.",
    ["037a666"] = "D'abord Shield sur toi. Ouvre avec Holy Fire de loin. Smite pendant que le monstre marche, puis Penance sur la même cible car Power in Light la fait frapper plus fort. Puis Mind Blast et Shadow Word: Pain. Pour finir Shadow Word: Death si un coup tue, sinon la baguette. Chaque fois que Weakened Soul disparaît tu peux te protéger de nouveau.",
    ["9d0affc"] = "Power Infusion : +20 % de dégâts et de soins pendant 15 secondes, sur toi ou un ami : lance-la sur toi juste avant d'ouvrir, chaque fois qu'elle est prête. Au 60 Inner Focus pour les urgences : le sort suivant est gratuit.",
    ["8e7cd8d"] = "Pour Discipline et Holy cherche de la puissance de soins et de la régénération de mana, puis Intelligence et Esprit. Choisis l'arme avec ces mêmes caractéristiques : peu importe que ce soit un bâton ou une à une main avec main gauche.",
    ["c5c1351"] = "Mets Shield et Renew sur toi avant le pull. Puis ouvre avec Holy Fire, Smite pendant que le monstre arrive, Mind Blast et Shadow Word: Pain. Finis avec Shadow Word: Death si ça tue ou avec la baguette.",
    ["575bdd0"] = "Holy Nova blesse tout ennemi proche et soigne le groupe : elle coûte beaucoup de mana, donc utilise-la avec plusieurs ennemis sur toi, ou quand elle est gratuite (Searing Light à partir du 43 : Holy Fire peut rendre gratuite la prochaine Holy Nova).",
    ["6953353"] = "Avant le pull mets sur toi Shield, Renew et Prayer of Mending (il soigne la prochaine fois que la cible subit des dégâts puis saute sur un autre du groupe, 10 secondes de recharge).",
    ["a5c9096"] = "Pour Holy cherche de la puissance de soins et de la régénération de mana, puis Intelligence et Esprit. Choisis l'arme avec ces mêmes caractéristiques.",
    ["aa71e89"] = "Backstab (il faut une dague, seulement dans le dos), Pick Pocket",
    ["2e3c463"] = "Slice and Dice, Sprint, Sap ; quête de classe (Blade of Cunning)",
    ["3a2246d"] = "Ambush (il faut une dague), Poised (passive)",
    ["8abd601"] = "Rupture ; quête des poisons : Instant Poison et Crippling Poison",
    ["6c840ea"] = "Shank (nouveau dans Forever)",
    ["f3d428e"] = "Mutilate (talent Assassination)",
    ["3e307c7"] = "Death Mark (talent Subtlety), Slice and Dice rang 2",
    ["f14c847"] = "Shank rang 2",
    ["a554ba3"] = "Marche jusqu'au monstre et utilise Sinister Strike tant que tu as des points de combo, puis Eviscerate : plus de points, coup plus fort. Stealth peut rester sur la barre pour l'instant. Si le combat tourne mal : Evasion et Gouge pour arrêter une incantation ou gagner quelques secondes.",
    ["44b2b7e"] = "Slice and Dice (un finisseur : tu attaques 20 % plus vite, plus longtemps avec plus de points), Sprint (50 % plus rapide pendant 15 secondes, ne rompt pas Stealth) et Sap pour sortir un humanoïde du combat avant de commencer.",
    ["665b56f"] = "Rupture : un saignement plus long avec plus de points. Avec la quête des poisons, Instant Poison et Crippling Poison.",
    ["d06b2e0"] = "Shank : un coup de la main gauche qui ne peut pas rater ; le premier rang coûte 5 d'énergie, en rend 15 et se recharge en 10 secondes. À partir du 26 Cheap Shot depuis la furtivité : étourdit 4 secondes et donne 2 points.",
    ["6974c7f"] = "Combat est le duelliste : il combat en mêlée avec l'arme que tu préfères, fonctionne avec n'importe quelle arme et n'a pas besoin de la furtivité pour commencer. C'est celle recommandée pour monter seul.",
    ["cea5a19"] = "Riposte : après une de tes parades elle s'illumine et frappe pour une fois et demie les dégâts de l'arme, désarme le monstre pendant 6 secondes et ne coûte que 10 d'énergie avec 6 secondes de recharge.",
    ["5288c4d"] = "Instant Poison sur les deux armes. Cheap Shot depuis la furtivité pour un combat dur, sinon Sinister Strike tout de suite. Riposte juste après une parade. Sinister Strike pour les points avec Shank en recharge : les cinq premiers points dans Slice and Dice, les cinq suivants dans Eviscerate.",
    ["869d1bf"] = "Avec deux monstres sur toi : Blade Flurry (toutes les 2 minutes, pendant 15 secondes tu attaques 20 % plus vite et chaque coup touche aussi un deuxième proche).",
    ["9fb5eb8"] = "Adrenaline Rush (toutes les 5 minutes : l'énergie revient deux fois plus vite pendant 15 secondes) pour un monstre dangereux.",
    ["f8cc28b"] = "Cold Blood juste avant un gros Eviscerate.",
    ["625324b"] = "Armure de cuir avec Agilité : c'est celle que tu veux. Toucher (Hit), critique, puissance d'attaque et Endurance sont utiles. Combat peut utiliser tout type d'arme, car Hack and Slash donne un bonus pour chacune : épées et haches, dagues et armes de poing, masses.",
    ["d01cb25"] = "Assassination est l'empoisonneur : poisons et finisseurs deviennent de plus en plus forts, et au 40 arrive Mutilate.",
    ["9eb3d72"] = "Instant Poison sur les deux armes. Depuis la furtivité ouvre avec Garrote ou Cheap Shot. Sinister Strike pour les points et Shank en recharge. Slice and Dice, puis Eviscerate ; garde Cold Blood pour un gros Eviscerate.",
    ["33aceb3"] = "Venom : pendant 6 secondes après chaque Shank tes poisons frappent 30 % plus fort et 20 % plus souvent. Shank en recharge.",
    ["88ede56"] = "Mutilate construit les points : il frappe avec les deux armes, 20 % plus fort sur une cible empoisonnée, et donne 2 points. Il faut deux dagues. Slice and Dice, Shank en recharge pour Venom, puis Eviscerate ; Cold Blood sur un gros Eviscerate.",
    ["20500ff"] = "Armure de cuir avec Agilité. Assassination a besoin de dagues pour Backstab, Ambush et Mutilate. Toucher (Hit), critique, puissance d'attaque et Endurance sont utiles.",
    ["5259278"] = "Subtlety est l'embusqueur : il ouvre chaque combat depuis l'ombre avec une dague en main.",
    ["64f4a07"] = "Dague dans la main droite, Instant Poison sur les deux armes. Approche-toi par derrière le monstre, Premeditation, puis Ambush, puis Ghostly Strike, puis Garrote. Sinister Strike construit le reste ; Shank en recharge pour l'énergie ; Eviscerate termine.",
    ["37c1365"] = "Hemorrhage construit les points à la place de Sinister Strike.",
    ["c0f22d5"] = "Hemorrhage et Shank construisent les points, et avec Boot Knife chaque Shank en vaut deux. Death Mark stocke les dégâts pendant 6 secondes : dépense-y un jeu complet de points quand le monstre vit assez longtemps, puis Eviscerate pour finir. Si le combat tourne mal, Preparation réinitialise Premeditation, Ghostly Strike et tes autres recharges.",
    ["a993dd2"] = "Armure de cuir avec Agilité. Subtlety garde une dague dans la main droite (Ambush et Backstab l'exigent). Toucher (Hit), critique, puissance d'attaque et Endurance sont utiles.",
    ["abbb551"] = "Earth Shock ; quête du totem de terre : Stoneskin Totem",
    ["8e8845b"] = "Quête du totem de feu : Searing Totem",
    ["2be8a5e"] = "Ghost Wolf, Frost Shock, Lesser Healing Wave, Frostbrand Weapon, Healing Stream Totem (quête du totem d'eau), Call of the Elements, Totemic Recall",
    ["0a8c77d"] = "Windfury Weapon, Reincarnation (il faut un Ankh), Astral Recall, Grounding Totem",
    ["47fd721"] = "Chain Lightning, Windfury Totem ; quête du totem d'air (les armes de la tempête)",
    ["b821239"] = "Chain Heal, armure de mailles",
    ["d6b5209"] = "Rockbiter Weapon reste sur l'arme et à partir du 8 Lightning Shield se met avant le pull. Ouvre avec Lightning Bolt et dès qu'il arrive Earth Shock, qui est instantané ; contre un lanceur garde le choc pour interrompre son incantation. Quand le monstre est sur toi, les coups de mêlée le finissent. Si un autre monstre arrive, pose Earthbind Totem : il le ralentit et te laisse faire du kiting. À la fin du combat Healing Wave si tu es blessé.",
    ["fa734a3"] = "Chaque spécialisation a un rôle clair : Enhancement combat en mêlée avec une grosse arme, des totems et des chocs ; Elemental reste à distance avec Lightning Bolt, Chain Lightning et Fire Nova ; Restoration soigne et reste en groupe ou en donjon, pas seul à faire des quêtes. Si tu n'as plus de mana, Enhancement continue à frapper (la mort prend plus de temps), Elemental souffre davantage.",
    ["b74be3c"] = "Flame Shock frappe tout de suite avec le feu puis brûle pendant 12 secondes. Flametongue Weapon ajoute des dégâts de feu à chaque coup ; Searing Totem est une petite tourelle qui tire sur un ennemi proche.",
    ["35c7293"] = "Enhancement est la spécialisation que nous recommandons pour les quêtes. Elle a ses points faibles : une arme médiocre baisse beaucoup les dégâts, les coûts de mana au début pèsent et contre beaucoup d'ennemis à la fois elle peine.",
    ["028a6b7"] = "Stormstrike frappe tout de suite avec tous les dégâts de l'arme toutes les 8 secondes, et la cible subit 20 % de plus de ton prochain Lightning Bolt, Chain Lightning ou Earth Shock.",
    ["a94041d"] = "Stormstrike chaque fois qu'il est prêt, et juste après Earth Shock (le coup de Stormstrike rend le choc plus fort). Rockbiter Weapon toujours sur l'arme et Lightning Shield sur toi. Avant le pull Strength of Earth et Mana Spring et, si le mana le permet, Searing Totem ou Magma Totem. Ouvre avec Lightning Bolt rang 1 (le moins cher), puis les coups normaux font le reste. Fire Nova seulement si les monstres sont dans le rayon de ton totem de feu et que tu as encore du mana. Après la mort Healing Wave, et bois si le mana est bas.",
    ["18a8896"] = "Windfury Weapon sur l'arme à la place de Rockbiter : chaque coup a 20 % de chances de donner deux attaques en plus, c'est la grosse pièce d'Enhancement. Si une esquive ou une parade réinitialise Stormstrike, appuie de nouveau tout de suite. Windfury Totem, avec Grounding Totem à sa place contre les lanceurs.",
    ["f3777c4"] = "Maelstrom Weapon : tes coups accumulent jusqu'à 5 charges et chaque charge rend le prochain Lightning Bolt plus rapide et moins cher : à 5 charges lance Lightning Bolt au rang le plus haut. À partir du 46 Water Shield prend la place de Lightning Shield (on ne peut en avoir qu'un).",
    ["022a55d"] = "Pour Enhancement l'arme compte avant tout : l'idéal est une deux mains lente, entre 3,3 et 3,8 de vitesse. Ensuite Force et puissance d'attaque, avec l'Intelligence juste derrière, car elle alimente Mental Dexterity et le mana.",
    ["4540d89"] = "Earthbound : quand tu poses Earthbind Totem, les ennemis proches restent bloqués pendant 5 secondes.",
    ["bcd1d77"] = "Avant le pull Mana Spring Totem et un totem de feu (Searing contre un monstre, Magma contre plusieurs), Lightning Shield sur toi. Ouvre à la limite de portée avec Lightning Bolt, mets Flame Shock sur la cible et continue avec Lightning Bolt. Avec trois monstres ou plus Fire Nova à chaque fois qu'il est prêt. Earth Shock interrompt un lanceur et l'amène vers toi. Earthbind Totem quand les monstres approchent. Soigne-toi et bois à la fin.",
    ["13a3832"] = "Contre un seul monstre : Searing Totem, ouvre de loin avec Lightning Bolt, Flame Shock, continue avec Lightning Bolt. Contre trois ou plus : Magma Totem, ouvre avec Chain Lightning, Flame Shock sur l'un d'eux, puis Chain Lightning et Fire Nova à chaque recharge avec Lightning Bolt entre les deux.",
    ["2c3ba7a"] = "Lightning Mastery (15 secondes, puis 3 minutes) : pendant 15 secondes Lightning Bolt se lance plus vite et Chain Lightning ignore sa recharge. Utilise-le sur un élite ou un gros pull, sinon à chaque recharge.",
    ["b56c9ed"] = "Water Shield prend la place de Lightning Shield sur toi.",
    ["4688073"] = "Pour Elemental cherche de la puissance des sorts, avec l'Intelligence surtout pour le mana. À partir du niveau 40 tu peux porter de la maille.",
    ["b4ca62b"] = "Avant le pull Water Shield, Mana Spring Totem et les totems que le groupe peut utiliser. Pendant que quelqu'un subit des dégâts, Healing Wave est le cheval de bataille. Lesser Healing Wave se lance en 1,5 seconde et soigne moins pour le mana : garde-le pour les moments où le temps compte. Mana Tide Totem (12 secondes, 5 minutes de recharge) quand tout le groupe n'a plus de mana. Quand personne n'est en danger ajoute des dégâts : Lightning Bolt sur une cible, Fire Nova sur un groupe. Bois à la fin.",
    ["42937c0"] = "Nature's Swiftness (toutes les 3 minutes) : ton prochain sort de nature est instantané, donc une Healing Wave instantanée pour un ami sur le point de mourir. Windfury Totem s'il y a des joueurs en mêlée.",
    ["9b2d19c"] = "Riptide : soin dans le temps avec 12 secondes de recharge, et une Chain Heal lancée juste sur la cible de Riptide est 25 % plus forte. Chain Heal soigne la cible et deux autres alliés, donc couvre les dégâts répartis dans le groupe.",
    ["a86408d"] = "Pour Restoration cherche de la puissance de soins, avec l'Intelligence surtout pour le mana. À partir du niveau 40 tu peux porter de la maille.",
    ["c86a1be"] = "Voidwalker (quête de classe), Drain Soul, Healthstone",
    ["40cb6b4"] = "Succubus et Incubus (quêtes de classe), Demon Armor, Curse of the Elements, Rain of Fire, Ritual of Summoning",
    ["df7bfa2"] = "Felhunter (quête de classe), Hellfire",
    ["19e5308"] = "Howl of Terror, Felsteed (quête)",
    ["1c5b068"] = "Le démon entre en premier, puis Bane of Agony et Corruption ; seuls les monstres les plus durs reçoivent Immolate, parce que le démon les retient. L'ordre compte car les dégâts attirent l'attention : les premiers ticks d'Agony sont petits, donc le démon retient le monstre jusqu'à ce qu'un nouvel Immolate frappe assez fort pour le faire se tourner vers toi. Garde Demon Skin, saute les DOT sur un monstre presque mort et ne renouvelle pas Agony tant qu'il fait encore des dégâts. Tant que tu n'as pas de baguette Shadow Bolt termine le travail ; puis prends une baguette : chaque tir est du mana économisé pour le pull suivant.",
    ["ea42414"] = "Drain Soul est ta source principale de Soul Shards : un monstre non trivial qui meurt de son drain en donne toujours un. Quand tu en as peu, termine tes morts avec lui. Healthstone, Soul Stone et les invocations de Voidwalker, Succubus et Felhunter demandent des fragments.",
    ["72f97d5"] = "Drain Life change ta façon de lire l'écran : si la barre bleue est basse et que ta vie va bien, Life Tap ; si ta vie a vraiment baissé, Drain Life sur le monstre. Ainsi presque tout le temps mort disparaît.",
    ["51205f3"] = "Demon Armor à la place de Demon Skin. Avec Ritual of Summoning toi et deux compagnons amenez un membre du groupe encore loin. Un Fear te donne quelques secondes gratuites pour un bandage.",
    ["9d83c05"] = "Si tu joues seul, Affliction est le choix : la précision et une Corruption instantanée arrivent tôt. Curse of the Elements va à côté d'Agony. À partir du 25 Nightfall peut se déclencher sur les dégâts de Corruption, Drain Life ou Drain Soul, et le Shadow Bolt après le proc n'a pas de temps d'incantation. Tu peux prendre le talent des drains un peu avant le 30 et t'appuyer sur Drain Life à chaque combat.",
    ["04f03c2"] = "Siphon Life : un tick toutes les 3 secondes pendant 30 secondes, donc un monstre qui meurt en 10 n'en reçoit qu'un tiers. Garde-le pour les longs combats.",
    ["703c37f"] = "Demonic Sacrifice : tu sacrifies le Felhunter et pendant deux heures tu récupères 3 % de ta vie totale toutes les 4 secondes ; invoquer un démon l'annule, donc à partir d'ici tu fais les quêtes presque sans familier.",
    ["2dbcea6"] = "Wrack : tu canalises pendant 6 secondes, il fait des dégâts d'ombre, et tes autres DOT d'ombre sur cette cible frappent 10 % plus fort tant qu'il dure.",
    ["edb7e47"] = "Choisis des armes avec puissance des sorts, car tu ne les utiliseras presque jamais pour frapper. Au début une amélioration de baguette bat presque toutes les autres ; ensuite la puissance des sorts passe en premier. L'Endurance est de la vie en plus à transformer en mana avec Life Tap, l'Intelligence une réserve de mana plus grande, l'Esprit rapporte plus à chaque Life Tap.",
    ["1c3a6a3"] = "Si tu préfères regarder le démon travailler, Demonology : avec Demonic Brand à partir du 25. À partir du 25 Searing Pain pose une marque sur la cible pendant 10 secondes, et au plus les six premiers coups de ton démon font des dégâts en plus : renouvelle-la avec un Searing Pain rapide sur ce que combat le démon et remplis les trous avec les DOT et la baguette.",
    ["00d4a86"] = "Soul Link : 30 % de chaque coup direct sur toi va au démon, et vous faites tous les deux 3 % de dégâts en plus. Il se perd quand tu changes de démon : relance-le chaque fois.",
    ["a3cee7a"] = "Demonic Pact : le sacrifice survit au changement de démon, sauf si tu invoques justement celui que tu as sacrifié. En donjon sacrifie l'Imp (15 % de dégâts d'ombre en plus) ; en quêtes en solo le Felhunter pour ses soins, et combats à côté d'un Voidwalker, Succubus ou Incubus. À partir du 27 tu peux aussi monter en Affliction et changer de spécialisation : tu as les points pour les trois rangs de Demonic Brand.",
    ["545f2c9"] = "Destruction est jouable à partir du 10, mais devient beaucoup plus forte au 39 et au 40, et reste plus longtemps immobile à lancer que les deux autres : tu peux aussi la choisir plus tard.",
    ["0b5d29c"] = "Shadowburn : un coup instantané qui coûte un Shard et te le rend si une cible non triviale meurt dans les 8 secondes.",
    ["124afde"] = "L'ouverture change : Shadow Bolt à portée maximale et Immolate pendant que le trait est encore en vol. Ainsi le monstre vient vers toi et pas vers le démon, donc choisis des combats que tu peux conclure vite. Shadowburn achève les monstres ; mieux vaut garder Conflagrate pour la fin de ton Immolate.",
    ["07ea333"] = "Avec Shadow and Flame, Conflagrate augmente tes dégâts d'ombre de 20 % et Shadowburn tes dégâts de feu de 20 % ; Conflagrate ne consomme plus Immolate et Shadowburn rend toujours le Shard. À partir du 39 il n'y a aucune raison de les retenir.",
    ["609f38c"] = "Incinerate fait 25 % de plus à tout ce qui brûle déjà à cause de ton Immolate.",
    ["a1d5005"] = "Defensive Stance, Taunt, Sunder Armor (quête de classe), Bloodrage",
    ["b87bfb2"] = "Revenge, Demoralizing Shout, Tactical Mastery (s'apprend chez le maître)",
    ["a61955b"] = "Victory Rush, Cleave, Slam, Retaliation ; tu peux utiliser deux armes",
    ["323f468"] = "Berserker Stance, Berserker Rage, Intercept (quête de classe)",
    ["b289adb"] = "Armure de plaques et monture",
    ["2debde0"] = "Battle Shout avant le pull, Charge, Rend sur ce qui vit longtemps, puis laisse les coups normaux accumuler de la rage. Heroic Strike seulement avec de la rage dont tu n'as pas besoin : il remplace un coup normal et ce coup ne donne pas de rage. Avec plusieurs monstres Thunder Clap ; ne dépense pas de rage sur un monstre qui va mourir.",
    ["f98c5d6"] = "Bloodrage entre deux pulls : il coûte un peu de vie et donne 10 de rage tout de suite et 10 en 10 secondes. Ne commence jamais un combat sans rage.",
    ["970305a"] = "Victory Rush chaque fois qu'il s'illumine : après une mort qui donne de l'expérience tu as 20 secondes, il fait des dégâts et te soigne de 10 %, 30 secondes de recharge et ne coûte pas de rage.",
    ["a60b4a3"] = "À partir du 14 Revenge est ton attaque principale : utilise-le chaque fois qu'il s'illumine (après un blocage, une esquive ou une parade). Passe à bouclier et arme à une main. Thunder Clap et Demoralizing Shout sur les groupes.",
    ["41fd2f0"] = "Charge, puis reste en Defensive Stance. Garde Shield Block contre ceux qui te frappent en mêlée, et saute Shield Block contre les lanceurs. Revenge chaque fois qu'il s'illumine ; Rend et quelques Sunder Armor sur les monstres qui vivent longtemps ; Thunder Clap et Demoralizing Shout sur les groupes.",
    ["b604238"] = "Avec Vanguard tu peux faire Charge depuis Defensive Stance : tu peux ouvrir un pull sans changer de posture, si tu es hors combat.",
    ["c9e7c22"] = "Shield Wall : 60 % de dégâts en moins pendant 12 secondes, pour les pulls qui tournent mal.",
    ["3f0c2f4"] = "Shield Slam est le coup le plus fort (les dégâts croissent avec ta valeur de blocage) : utilise-le en premier et Revenge juste après. Si tu as peu de rage, Revenge d'abord, il coûte moins.",
    ["846367b"] = "Protection veut surtout de la Force (chaque point donne 2 de puissance d'attaque et de valeur de blocage). Pour l'arme prends le meilleur DPS : Revenge et Shield Slam ne dépendent pas de l'arme. L'Agilité compte moins : elle donne critique, esquive et armure mais pas de puissance d'attaque.",
    ["fabdcb6"] = "Rend d'abord, puis Overpower chaque fois qu'il s'illumine (après une esquive de la cible).",
    ["f29cf52"] = "Rend, puis Overpower quand il s'illumine. À partir du 20 Slam juste après un coup.",
    ["60998aa"] = "Sweeping Strikes : tes cinq prochains coups touchent aussi un deuxième ennemi proche, c'est un grand saut. Commence sur un monstre tant que tu as de la rage en plus, puis attire un deuxième monstre et utilise Sweeping Strikes et Cleave sur les deux.",
    ["efc030d"] = "Avec Bloodthrill, si Rend est sur la cible les coups de la main droite ont 20 % de chances de déclencher Overpower : Rend reste dans la rotation jusqu'au 60.",
    ["98a8fec"] = "Mortal Strike est ta nouvelle attaque principale.",
    ["7caf705"] = "L'arme compte plus que tout : cherche le DPS le plus haut, et pour Arms une deux mains lente (chaque coup et Mortal Strike et Slam font plus de dégâts). Pour le reste d'abord Toucher (Hit, car un coup raté ne donne ni dégâts ni rage), puis Force et Critique. L'Agilité donne critique et esquive mais aucune puissance d'attaque.",
    ["ce62f29"] = "Rend sur les monstres qui vivent longtemps, Overpower quand la cible esquive. Si un deuxième monstre est à côté de la cible, dépense la rage en plus dans Cleave. Choisis une main gauche rapide : plus de coups, plus de rage.",
    ["1879df1"] = "Death Wish : pendant 30 secondes tu fais 20 % de dégâts physiques en plus et ne peux pas être effrayé, mais tu subis 5 % de dégâts en plus. Reckless Swings (31) : il coûte un peu de vie et les quatre prochains coups donnent chacun 5 de rage en plus.",
    ["0d27ce4"] = "Avec Whirlwind (niveau 36) c'est ta touche principale, même contre un seul monstre : la recharge tombe à 8 secondes et il frappe le plus proche avec 30 % de dégâts en plus.",
    ["308a3c5"] = "Bloodthirst chaque fois que Whirlwind est en recharge. À partir du 50 tu as Recklessness.",
    ["2d76abd"] = "L'arme compte plus que tout : cherche le DPS le plus haut. Pour la main gauche une rapide (plus de coups, plus de rage). Pour le reste d'abord Toucher (Hit), puis Force et Critique. L'Agilité donne critique et esquive mais aucune puissance d'attaque.",
}
